 * mới — không có $shopifyData/$liquidEngine và đọc innerHTML ngay sau mount nên không
 * tự fetch được. Nó đọc lại đúng data mà builder đã tải, giống cách mixin liquid
 * dùng lại HTML CSR cho preview.
 */
const sharedProductCache = new Map<string, ProductData>();
let sharedShopData: any = null;

