        },

        image() {
            if(!this.data.settings){
                return
            }
            let { image = {}, size, size_custom } = this.data.settings;
            if (Object.keys(image).length === 0) {
                return null;
            }
            if (size === 'custom') {
                size = size_custom;
            }
            else if(size) {
                size = {width: size.split('x')[0], height: size.split('x')[1]};
            }

            return {
                alt: image.alt || image.name,
                ...Object.keys(image)
                    .filter((k) => k.startsWith('value'))
                    .reduce((acc, cur) => {
                        acc[cur] = this.$helpers.resizeImage(image[cur], size);
                        return acc;
                    }, {}),
            };
        },

        isCaption() {
            return this.data.settings?.use_caption && this.data.settings?.caption;
        },

        imageHotspot() {
            return this.data.settings;
        },
        activeMe() {
            return (this.editingElement?.data?.id ?? 0) === this.data.id;
        },
        isContentEditable() {
            return this.$store.getters['builder/isContentEditable'];
        },
        editingElementId() {
            return this.$store.getters['builder/editingElementId'];
        },
        isEditingThisElement() {
            if (this.exporting) return false;
            return this.editingElementId === this.data.id && this.isContentEditable;
        },
        isEditingAnyHotspotInline() {
            return this.inlineItemIndex !== null && this.isEditingThisElement;
        },

        /**
         * Chỉ fetch product ở builder: export để JS runtime tự đổ data, còn app preview
         * không có $shopifyData (nó dùng lại `sharedProductCache`).
         */
        shouldUseProductCSR() {
            return this.exporting !== true && !!this.$shopifyData;
        },

        /** Handle của tất cả hotspot kiểu product, đã loại trùng. */
        hotspotProductHandles() {
            const items = this.data.settings?.items || [];

            return items.reduce((handles: string[], item: any) => {
                const handle = item?.source === 'product' ? item?.product?.value : null;
                if (handle && typeof handle === 'string' && !handles.includes(handle)) {
                    handles.push(handle);
                }
                return handles;
            }, [] as string[]);
        },

        hotspotProductHandlesKey() {
            return this.hotspotProductHandles.join(',');
        },

        javascript() {
            if (this.imageHotspot && this.imageHotspot.items && this.imageHotspot.items.length) {
                this.image;
                return function () {
                    function stripContent(htmlStr) {
                        if (htmlStr && htmlStr.length > 0) {
                            const div = document.createElement('div');
                            div.innerHTML = htmlStr;
                            return div.textContent || div.innerText || '';
                        }
                        return '';
                    }

                    function truncateWords(value, length, overflowSuffix) {
                        if(!value || !length) return '';
                        let words = value.split(' ');
                        if(words.length < length)
                        {
                            return value;
                        }

                        return words.slice(0, length).join(' ') + (overflowSuffix || '')
                    }

                    if(!this.$el) return;
                    const $el = this.$el, isLive = this.isLive;
                    const elements = $el.querySelectorAll(
                        '.ecom__element.element__image-hotspot .element__image-hotspot--text'
                    );
                    if(!this.isLive)
                    {
                        $el.querySelectorAll('.element__image-hotspot--content-btn')
                            .forEach((btn) => {
                                btn.addEventListener('click', function(e){
                                    e.preventDefault();
                                    e.stopPropagation();
                                    let href = this.getAttribute('href');
                                    if (href && href.indexOf('/product') >= 0) {
                                        e.preventDefault();
                                        window.open(window.EComposer.routes.domain + href);
                                    }
                                });
                            });
                    }
                    const regex = /^arrow-(top|left|right|bottom|auto)$/;

                    // get again product info
                    const loadProduct = async  function(element){
                        // Kiem tra helper TRUOC khi an anh: trang preview export khong co
                        // window.EComposer, neu an truoc roi return thi anh product mat luon.
                        if(!window.EComposer ||  !window.EComposer.getProduct )
                        {
                            console.log('EComposer theme helper not enabled');
                            return false;
                        }

                        element.querySelector('.element__image-hotspot--content-image').style.opacity = 0;
                        const loadingWrapper = element.querySelector('.ecom-hotspots-container-tooltip');
                        if(loadingWrapper) loadingWrapper.classList.add('ecom-loading-image');

                        const handle = element.getAttribute('data-handle');
                        const limit = element.getAttribute('data-limit');

                        var  result;
                        try {
                            if(element.dataset.product)
                            {
                                result = JSON.parse(element.dataset.product);
                                if(result.handle !== handle)
                                {
                                    result = await window.EComposer.getProduct(handle);
                                }
                            }
                            else
                            {
                                result = await window.EComposer.getProduct(handle);
                            }
                        } catch (e) {
                            // Fetch loi thi giu nguyen noi dung san co, khong de anh bi an
                            result = null;
                        }
                        const imageElement = element.querySelector(
                            '.element__image-hotspot--content-image'
                        );
                        const titleElement = element.querySelector(
                            '.element__image-hotspot--content-title'
                        );
                        const textElement = element.querySelector(
                            '.element__image-hotspot--content-text'
                        );
                        const buttonElement = element.querySelectorAll(
                            '.element__image-hotspot--content-btn'
                        );

                        if (result && result.id) {

                            const priceElement = element.querySelector('.element__image-hotspot--content-prices');
                            if(imageElement)
                                imageElement.src = result.featured_image;

                            if(titleElement)
                                titleElement.innerText = result.title;

                            if(textElement)
                                textElement.innerText = truncateWords(stripContent(result.description),parseInt(limit??20),'...') || '';

                            buttonElement.forEach(function(btn) {
                                btn.href = result.url;
                            })

                            if(priceElement)
                            {
                                let markup = `<span class="element__image-hotspot--content-price">${window.EComposer.formatMoney(result.price)}</span>`;
                                if(result.price < result.compare_at_price)
                                {
                                    markup+=  `<span class="element__image-hotspot--content-price--regular">${window.EComposer.formatMoney(result.compare_at_price)}</span>`;
                                }
                                priceElement.innerHTML = markup;
                            }
                            element.dataset.product = JSON.stringify(result);
                        }

                        if(loadingWrapper) loadingWrapper.classList.remove('ecom-loading-image');
                        element.querySelector('.element__image-hotspot--content-image').style.opacity = 1;

                    }
                    const windowWidth = window.innerWidth || document.documentElement.clientWidth || document.body.clientWidth;
                    const contents = $el.querySelectorAll(
                        '.element__image-hotspot--content'
                    );
                    elements.forEach((element, index) => {
                        const btn = element.querySelector('.element__image-hotspot--btn'),
                            block = element.closest('.ecom-block.ecom-core'),
                            column =  element.closest('.core__column--wrapper'),
                            section =  element.closest('.ecom-row.ecom-core');

                        const content = element.querySelector(
                            '.element__image-hotspot--content'
                        );
                        function clearCenterMobile() {
                            if (!content?.classList.contains('element__image-hotspot--content-centerMobile')) return;
                            content.style.position = '';
                            content.style.left = '';
                            content.style.top = '';
                            content.style.bottom = '';
                            content.style.right = '';
                            content.style.translate = '';
                            content.style.transform = '';
                        }
                        let type = element.getAttribute('data-source');
                        if(type === 'link') {
                            let redirectLink = element.getAttribute('data-redirect-link')?JSON.parse(element.getAttribute('data-redirect-link')):null;
                            btn.addEventListener('click', ()=>{
                                if(this.isLive == true){
                                    redirectLink?.href?(redirectLink.target?window.open(redirectLink.href,'_blank'):window.location.href = redirectLink.href):window.location.reload();
                                }
                            });
                        }else{
                            function activateElement() {
                                // Raise this element above sibling hotspot texts
                                elements.forEach(function(el) { el.style.zIndex = ''; });
                                element.style.zIndex = '103';
                            }
                            function deactivateElement() {
                                element.style.zIndex = '';
                            }
                            /**
                             * centerMobile: đặt tooltip vào giữa vùng nhìn thấy (viewport) bằng JS.
                             * position:fixed bị lệch khi tổ tiên có transform — dùng absolute + toạ độ.
                             *
                             *
                             * - window.innerWidth/innerHeight = layout viewport *tại thời điểm đọc*;
                             *   mobile (thanh URL ẩn/hiện), bàn phím, resize, widget (vd. Shopify Chat)
                             *   có thể làm thay đổi vài chục px giữa hai lần log.
                             * - Log từ shopifyChatV1Widget.js là context/script khác — không nhất thiết
                             *   trùng với window của trang hotspot.
                             * - Khi có window.visualViewport: dùng tâm visual viewport (vùng nhìn thực,
                             *   offsetLeft/Top + width/height) để khớp getBoundingClientRect().
                             * Fallback: tâm layout viewport (innerWidth/2, innerHeight/2).
                             */
                            function applyCenterMobile() {
                                const layoutW = window.innerWidth || document.documentElement.clientWidth || document.body.clientWidth;
                                if (layoutW >= 768){ return; }
                                if (!content.classList.contains('element__image-hotspot--content-centerMobile')){ return; }

                                const elRect = element.getBoundingClientRect();
                                const vv = window.visualViewport;
                                let centerX;
                                let centerY;
                                if (vv) {
                                    centerX = vv.offsetLeft + vv.width / 2;
                                    centerY = vv.offsetTop + vv.height / 2;
                                } else {
                                    centerX = layoutW / 2;
                                    centerY = window.innerHeight / 2;
                                }

                                content.style.position = 'absolute';
                                content.style.left = (centerX - elRect.left) + 'px';
                                content.style.top = (centerY - elRect.top) + 'px';
                                content.style.bottom = 'unset';
                                content.style.right = 'unset';
                                // Reset translate/transform từ class phía tooltip (tránh chồng offset).
                                content.style.translate = 'none';
                                content.style.transform = 'translate(-50%, -50%)';
                            }

                            function clickBtn () {
                                btn.addEventListener('click', (e) => {
                                // Builder: Vue already toggles ecom-hotspot-actived via tabOpened.
                                // DOM toggle here closes the popup immediately on first click.
                                if (!isLive) {
                                    e.stopPropagation();
                                    return;
                                }
                                if (!content.classList.contains('ecom-hotspot-actived')) {
                                    if(content.dataset.side == 'auto') {
                                        handlePositionTooltip();
                                    }
                                    addIndex(content);
                                    contents.forEach(function(content) {
                                        content.classList.remove('ecom-hotspot-actived')
                                    })
                                    content.classList.add('ecom-hotspot-actived', 'ecom_current_click');
                                    activateElement();
                                    applyCenterMobile();
                                    if(windowWidth < 768) {
                                        var userScroll = window.pageYOffset;
                                        window.document.addEventListener('scroll', function() {
                                            var newScroll = window.pageYOffset;
                                            if(userScroll - newScroll > 100 || newScroll - userScroll > 100){
                                                content.classList.remove('ecom-hotspot-actived');
                                                document.removeEventListener('click', doClose, true);
                                                deleteIndex(content);
                                                deactivateElement();
                                                clearCenterMobile();
                                            }
                                        })
                                    }
                                    let source = element.getAttribute('data-source');
                                    if(source === 'product' && isLive == true)
                                    {
                                        clearTimeout(itv);
                                        itv = setTimeout(()=>loadProduct(element),500);
                                    }
                                    setTimeout(() => {
                                        //content.focus();
                                        document.removeEventListener('click', doClose, true);
                                        document.addEventListener('click', doClose, true);
                                        content.classList.remove('ecom_current_click');
                                    }, 300);
                                    block && (block.style.zIndex = '99');
                                    column && (column.style.zIndex = '99');
                                    section && (section.style.zIndex = '99');
                                } else {
                                    deleteIndex(content);
                                    content.classList.remove('ecom-hotspot-actived');
                                    deactivateElement();
                                    clearCenterMobile();
                                    block && (block.style.zIndex = 'unset');
                                    column && (column.style.zIndex = 'unset');
                                    section && (section.style.zIndex = 'unset');
                                }
                            });
                            }
                            function handlePositionTooltip() {
                                const {width, height} = content.getBoundingClientRect(),
                                    {top: topP, right: rightP, left: leftP, bottom: bottomP} = content.closest('.ecom__element.element__image-hotspot .element__image-hotspot--text').getBoundingClientRect();
                                let side = 'left';
                                if(window.innerWidth - rightP < width || leftP < width || topP < height || bottomP < height) {
                                    if(window.innerWidth - rightP < width && leftP > width) {
                                        side = 'left';
                                    }
                                    if(leftP < width && window.innerWidth - rightP > width) {
                                        side = 'right';
                                    }
                                    if(window.innerWidth - rightP < width && leftP < width && topP > height) {
                                        side = 'top';
                                    }
                                    if(window.innerWidth - rightP < width && leftP < width && topP < height && bottomP + height < innerHeight) {
                                        side = 'bottom';
                                    }
                                }
                                const rex = /^element__image-hotspot--content-(top|left|right|bottom|auto)$/;
                                content.classList.forEach(className => {
                                    if (rex.test(className)) {
                                        content.classList.remove(className);
                                    }
                                });
                                content.classList.add('arrow-' + side);
                                content.classList.add('element__image-hotspot--content-'+side);
                            }
                            let itv;
                            if (btn && content) {
                                if(this.settings.trigger === 'hover'){
                                    if(window.innerWidth <= 767) {
                                        clickBtn();
                                    }
                                    else {
                                        element.addEventListener('mouseover', () => {
                                            if(content.dataset.side == 'auto') {
                                                handlePositionTooltip();
                                            }
                                            addIndex(content);
                                            contents.forEach(function(content) {
                                                content.classList.remove('ecom-hotspot-actived')
                                            })
                                            content.classList.add('ecom-hotspot-actived');
                                            activateElement();
                                            applyCenterMobile();
                                            if(windowWidth < 768) {
                                                var userScroll = window.pageYOffset;
                                                window.document.addEventListener('scroll', function() {
                                                    var newScroll = window.pageYOffset;
                                                    if(userScroll - newScroll > 100 || newScroll - userScroll > 100){
                                                        content.classList.remove('ecom-hotspot-actived');
                                                        document.removeEventListener('click', doClose, true);
                                                        deleteIndex(content);
                                                        deactivateElement();
                                                        clearCenterMobile();
                                                    }
                                                })
                                            }
                                            let source = element.getAttribute('data-source');
                                            if(source === 'product' && isLive == true)
                                            {
                                                loadProduct(element)
                                                // clearTimeout(itv);
                                                // itv = setTimeout(()=>loadProduct(element),100);
                                            }
                                            block && (block.style.zIndex = '99');
                                            column && (column.style.zIndex = '99');
                                            section && (section.style.zIndex = '99');
                                        });
                                        element.addEventListener('mouseleave', function () {
                                            deleteIndex(content);
                                            content.classList.remove('ecom-hotspot-actived');
                                            deactivateElement();
                                            clearCenterMobile();
                                            block && (block.style.zIndex = 'unset');
                                            column && (column.style.zIndex = 'unset');
                                            section && (section.style.zIndex = 'unset');
                                        });
                                    }

                                }
                                else
                                {
                                    clickBtn();
                                }
                            }
                        };

                        function closePopup() {
                                $el.querySelector('.element__image-hotspot--content.ecom-hotspot-actived:not(.ecom_current_click)') && $el.querySelector('.element__image-hotspot--content.ecom-hotspot-actived:not(.ecom_current_click)').classList.remove('ecom-hotspot-actived');
                                deleteIndex(content);
                                document.removeEventListener('click', doClose, true);
                                // Reset z-index of all hotspot texts
                                elements.forEach(function(el) { el.style.zIndex = ''; });
                                clearCenterMobile();
                                block && (block.style.zIndex = 'unset');
                                column && (column.style.zIndex = 'unset');
                                section && (section.style.zIndex = 'unset');
                            }

                            function doClose(e) {
                                const currentButton = e.target.closest('.element__image-hotspot--text');
                                if (
                                    e == undefined || (!e.target.closest('.ecom-hotspots-container-tooltip') && !currentButton)
                                ) {
                                    closePopup();
                                }
                            }
                    });

                    function addIndex(content) {
                        let column = content.closest('.ecom-column.ecom-core'), row = content.closest('.ecom-row.ecom-core');

                        if(column) {
                            column.style.zIndex = 101;
                        }
                        if(row) {
                            row.style.zIndex = 101;
                        }
                    }
                    function deleteIndex(content) {
                        let column = content.closest('.ecom-column.ecom-core'), row = content.closest('.ecom-row.ecom-core');
                        if(column) {
                            column.style.zIndex = '';
                        }
                        if(row) {
                            row.style.zIndex = '';
                        }
                    }
                    const image = $el.querySelector('.element__image-hotspot--img > img');
                    if(image) {
                        const handleImageLoad = () => {
                            $el.querySelector('.ecom-element__image-hotspot--wrapper').classList.add('ecom-image-hotspot-loaded');
                            image.removeEventListener('load', handleImageLoad);
                        };
                        if (image.complete) {
                            handleImageLoad();
                        } else {
                            image.addEventListener('load', handleImageLoad);
                        }
                    }
                };
            }
            return function () {};
        },

        screens() {
            return this.$store.getters['builder/screens'];
        },
        focalPoint() {
          // focal point
          let style = {};
          let { image = {} } = this.data.settings;
          if (Object.keys(image).length === 0) {
              return null;
          }
          if(image?.left && image?.top) {
            style['object-position'] = `${image?.left}% ${image?.top}%`;
          }
          return style;
          // end focal point
        },

