                                    '500x500': '500 x 500px',
                                    '': this.$t('original'),
                                    // custom: this.$t('custom')
                                }
                            },
                            css: {
                                isCss: false
                            }
                        },
                        {
                            type: 'popup',
                            label: this.$t('fetch_priority'),
