         * Tính toán hệ số bù trừ vị trí cho các hotspot cũ (không có positionV2).
         * Item cũ lưu tọa độ % tính từ this.$el (cơ chế drag cũ).
         * Sau khi thêm position:relative vào wrapper, display anchor thay đổi thành wrapper.
         * Nếu $el và wrapper khác kích cỡ/vị trí, cần bù trừ để giữ nguyên vị trí cũ.
         */
        /**
         * Cập nhật hotspotCoordStyle để overlay div khớp với khu vực hiển thị của picture.
         * Được gọi khi mount và mỗi làn wrapper resize (ResizeObserver).
         * Nhờ đó, left/top % của hotspot luôn tương đối với ảnh, không phải wrapper.
         */
        _updateHotspotCoord() {
            const wrapper = this.$el?.querySelector('.ecom-element__image-hotspot--wrapper');
            const img     = this.$el?.querySelector('.element__image-hotspot--img');
            if (!wrapper || !img) return;

            const wRect = wrapper.getBoundingClientRect();
            const iRect = img.getBoundingClientRect();
            if (!wRect.width || !wRect.height) return;

            this.hotspotCoordStyle = {
                left:   (iRect.left - wRect.left) + 'px',
                top:    (iRect.top  - wRect.top)  + 'px',
                width:  iRect.width  + 'px',
                height: iRect.height + 'px',
            };
        },

        /**
         * Trả về inline style { left, top } cho hotspot.
         * Tất cả giá trị x/y đều là % của coord div (= kích thước ảnh),
         * nên responsive chính xác ở mọi độ phân giải.
         */
        hotspotPosition(item) {
            // V2 items (moved after the update): centered to prevent visual drift on resize.
            if (item.positionV2) {
                return {
                    left: (item.horizontalPosition ?? 0) + '%',
                    top:  (item.verticalPosition   ?? 0) + '%',
                    transform: 'translate(-50%, -50%)'
                };
            }

            // Legacy items: retain top-left behavior if they haven't been re-dragged
            return {
                left: (item.horizontalPosition ?? 0) + '%',
                top:  (item.verticalPosition   ?? 0) + '%',
            };
        },

        /** Gán 'none' khi thiếu key để dropdown popup khớp option (dữ liệu cũ trước khi có field). */
        applyAnimationDefaultsIfMissing() {
            const s = this.data?.settings;
            if (!s || typeof s !== 'object') return;
            const missing = (v: unknown) => v === undefined || v === null || v === '';
            if (missing(s.tooltipAnimation)) {
                s.tooltipAnimation = 'none';
            }
            const items = s.items;
            if (!Array.isArray(items)) return;
            for (let i = 0; i < items.length; i++) {
                const item = items[i];
                if (!item || typeof item !== 'object') continue;
                if (missing(item.hotspotsAnimation)) {
                    item.hotspotsAnimation = 'none';
                }
            }
        },
        quickToolBar() {
            return ['image', 'size'];
        },
        isBuilderHotspotPopupOpen(index) {
            if (this.exporting) return false;
            const tabOpened = this.data.settings?.items?.tabOpened;
            return tabOpened === index || (this.inlineItemIndex === index && this.isEditingThisElement);
        },
        showHotspotBtnLabel(item) {
            if (!item) return false;
            if (this.exporting) {
                return !!(item.hotspotLabel && item.hotspotLabel.length);
            }
            return item.isShowLabel === true || !!(item.hotspotLabel && item.hotspotLabel.length);
        },
        isEditingHotspotField(index, field) {
            return (
                this.inlineItemIndex === index &&
                this.inlineEditField === field &&
                this.isEditingThisElement
            );
        },
        getHotspotFieldRaw(index, field) {
            const item = this.data.settings?.items?.[index];
            if (!item) return '';
            if (field === 'button_label') return item.button_label;
            if (field === 'hotspotLabel') return item.hotspotLabel;
            if (field === 'titleCard') return item.titleCard;
            if (field === 'textCard') return item.textCard;
            if (field === 'buttonCard') return item.buttonCard;
            return '';
        },
        hotspotInlineValueMode(field) {
            const plain = ['hotspotLabel', 'titleCard', 'button_label', 'buttonCard'];
            return plain.includes(field) ? 'text' : 'html';
        },
        textLooksDynamic(text) {
            const s = String(text || '');
            return s.includes('{{') || s.includes('{%');
        },
        onHotspotInlineMouseDown(index, field, e) {
            if (this.exporting) return;
            if (
                this.inlineItemIndex !== null &&
                (this.inlineItemIndex !== index || this.inlineEditField !== field) &&
                this.isContentEditable
            ) {
                e.preventDefault();
            }
        },
        editHotspotField(index, field, e) {
            if (this.exporting) return;
            const item = this.data.settings?.items?.[index];
            if (!item) return;
            if (field === 'hotspotLabel') {
                if (!this.showHotspotBtnLabel(item) && !item.isShowLabel) return;
                if (!item.isShowLabel) {
                    item.isShowLabel = true;
                }
            } else if (field === 'button_label') {
                if (item.source !== 'product') return;
            } else if (field === 'titleCard' || field === 'textCard' || field === 'buttonCard') {
                if (item.source !== 'custom') return;
            } else {
                return;
            }
            const raw = this.getHotspotFieldRaw(index, field);
            const fallback = field === 'button_label' ? 'View Details' : '';
            const check = raw || fallback;
            if (check && this.textLooksDynamic(String(check))) return;
            if (this.isContentEditable && !this.isEditingThisElement) {
                this.$store.commit('builder/setIsContentEditable', false);
            }
            if (
                this.inlineItemIndex !== null &&
                (this.inlineItemIndex !== index || this.inlineEditField !== field)
            ) {
                this.syncHotspotInlineToModel();
            }
            this.inlineItemIndex = index;
            this.inlineEditField = field;
            this.editingValue = String(raw ?? fallback ?? '');
            this.currentEditEl = e.currentTarget;
            this.setEditingElement(index, { forceOpen: true });
            this.$store.commit('builder/setEditingElementId', this.data.id);
            this.$store.commit('builder/setIsContentEditable', true);
            this.focusHotspotInlineField();
        },
        focusHotspotInlineField() {
            if (this.exporting || this.inlineItemIndex === null || !this.inlineEditField) return;
            if (!this.isEditingThisElement) return;
            const raw = this.getHotspotFieldRaw(this.inlineItemIndex, this.inlineEditField);
            const fallback = this.inlineEditField === 'button_label' ? 'View Details' : '';
            this.editingValue = String(raw ?? fallback ?? '');
            this.$nextTick(() => {
                if (!this.isEditingHotspotField(this.inlineItemIndex, this.inlineEditField)) return;
                placeCaretAtEnd(this.currentEditEl, this.idoc());
            });
        },
        onHotspotInlineInput(index, ev) {
            if (this.exporting) return;
            if (this.inlineItemIndex !== index || !this.inlineEditField || !this.isEditingThisElement) return;
            const item = this.data.settings?.items?.[index];
            if (!item) return;
            const source = this.getHotspotFieldRaw(index, this.inlineEditField);
            if (source && this.textLooksDynamic(String(source))) return;
            const target = ev?.target;
            if (!target) return;
            const next = getContentEditableValue(
                target,
                this.hotspotInlineValueMode(this.inlineEditField)
            );
            if (this.inlineEditField === 'button_label') {
                if (item.button_label !== next) item.button_label = next;
            } else if (this.inlineEditField === 'hotspotLabel') {
                if (item.hotspotLabel !== next) item.hotspotLabel = next;
            } else if (this.inlineEditField === 'titleCard') {
                if (item.titleCard !== next) item.titleCard = next;
            } else if (this.inlineEditField === 'textCard') {
                if (item.textCard !== next) item.textCard = next;
            } else if (this.inlineEditField === 'buttonCard') {
                if (item.buttonCard !== next) item.buttonCard = next;
            }
        },
        handleHotspotInlineBlur() {
            if (this.exporting) return;
            setTimeout(() => {
                const active = document.activeElement;
                const root = this.$el;
                if (
                    active &&
                    root?.contains(active) &&
                    (active.classList?.contains('ecom-html') ||
                        active.closest?.('.element__image-hotspot--btn-label, .element__image-hotspot--content-title, .element__image-hotspot--content-text, .element__image-hotspot--content-btn'))
                ) {
                    return;
                }
                this.syncHotspotInlineToModel();
                if (!this.isBlur) return;
                setTimeout(() => {
                    this.$store.commit('builder/setIsContentEditable', false);
                    this.inlineItemIndex = null;
                    this.inlineEditField = null;
                    this.currentEditEl = null;
                }, 200);
            }, 0);
        },
        syncHotspotInlineToModel() {
            if (this.inlineItemIndex === null || !this.inlineEditField || !this.currentEditEl) return;
            const row = this.data.settings.items[this.inlineItemIndex];
            if (!row) return;
            const el = this.currentEditEl;
            const field = this.inlineEditField;
            const next = getContentEditableValue(
                el,
                this.hotspotInlineValueMode(field)
            );
            if (field === 'button_label' && row.button_label !== next) {
                row.button_label = next;
            } else if (field === 'hotspotLabel' && row.hotspotLabel !== next) {
                row.hotspotLabel = next;
            } else if (field === 'titleCard' && row.titleCard !== next) {
                row.titleCard = next;
            } else if (field === 'textCard' && row.textCard !== next) {
                row.textCard = next;
            } else if (field === 'buttonCard' && row.buttonCard !== next) {
                row.buttonCard = next;
            }
        },
        stripContent(htmlStr) {
            if (htmlStr && htmlStr.length > 0) {
                const div = document.createElement('div');
                div.innerHTML = htmlStr;
                return div.textContent || div.innerText || '';
            }
            return '';
        },
        truncateWords(value, length, overflowSuffix) {
            if(!value || !length) return '';
            let words = value.split(' ');
            if(words.length < length)
            {
                return value;
            }

            return words.slice(0, length).join(' ') + (overflowSuffix || '')
        },

        /**
         * Nạp product thật cho các hotspot kiểu product.
         * Chỉ gọi cho handle chưa từng fetch — kể cả handle không tìm thấy — để việc
         * sửa settings (kéo hotspot, đổi màu...) không bắn lại request mỗi lần.
         */
        async loadHotspotProducts() {
            if (!this.shouldUseProductCSR) return;

            if (!this._csrFetchedHandles) this._csrFetchedHandles = new Set<string>();

            const pending = this.hotspotProductHandles.filter(
                (handle: string) => !this._csrFetchedHandles.has(handle)
            );
            if (!pending.length) return;

            pending.forEach((handle: string) => this._csrFetchedHandles.add(handle));

            const chunks: string[][] = [];
            for (let i = 0; i < pending.length; i += PRODUCT_BATCH_SIZE) {
                chunks.push(pending.slice(i, i + PRODUCT_BATCH_SIZE));
            }

            try {
                const results = await Promise.all(
                    chunks.map((handles) =>
                        this.$shopifyData
                            .getProducts({ type: 'products_batch', handles, limit: handles.length })
                            .catch(() => [] as ProductData[])
                    )
                );

                const loaded: Record<string, ProductData> = {};
                results.flat().forEach((product: ProductData) => {
                    if (product?.handle) {
                        loaded[product.handle] = product;
                        sharedProductCache.set(product.handle, product);
                    }
                });

                if (Object.keys(loaded).length) {
                    this.csrProducts = { ...this.csrProducts, ...loaded };
                }
            } catch (_) {
                // Không có data thật thì giữ nguyên nội dung mẫu.
            }
        },

        debouncedLoadHotspotProducts() {
            if (this._csrTimer) clearTimeout(this._csrTimer);
            this._csrTimer = setTimeout(() => this.loadHotspotProducts(), 300);
        },

        /**
         * Product thật của hotspot, null nếu chưa load được.
         * `csrProducts` (reactive) cho builder tự cập nhật khi fetch xong; app preview
         * không fetch được nên đọc thẳng cache dùng chung builder đã đổ đầy.
         */
        hotspotProduct(item: any) {
            if (this.exporting === true || item?.source !== 'product') return null;

            const handle = item?.product?.value;
            if (!handle) return null;

            return this.csrProducts[handle] || sharedProductCache.get(handle) || null;
        },

        /** Shop data để format tiền — app preview không có $liquidEngine nên dùng bản builder đã lấy. */
        hotspotShopData() {
            const shopData = this.$liquidEngine?.getShopData?.() || null;
            if (shopData) sharedShopData = shopData;

            return shopData || sharedShopData;
        },

        hotspotProductTitle(item: any) {
            if (this.exporting === true) return '';

            const title = this.hotspotProduct(item)?.title || item?.product?.name;
            return this.escapeHtmlText(title || SAMPLE_PRODUCT_TITLE);
        },

        /**
         * Markup giá giống hệt bản live (`loadProduct` trong computed javascript):
         * giá bán trước, giá gạch (compare at price) chỉ hiện khi đang sale.
         */
        hotspotProductPrice(item: any) {
            if (this.exporting === true) return '';

            const product = this.hotspotProduct(item);
            if (!product) {
                return `<span class="element__image-hotspot--content-price">${SAMPLE_PRODUCT_PRICE}</span>`;
            }

            const shopData = this.hotspotShopData();
            let markup = `<span class="element__image-hotspot--content-price">${formatMoney(product.price, shopData)}</span>`;

            if (product.compare_at_price && product.price < product.compare_at_price) {
                markup += `<span class="element__image-hotspot--content-price--regular">${formatMoney(product.compare_at_price, shopData)}</span>`;
            }

            return markup;
        },

        hotspotProductDescription(item: any) {
            if (this.exporting === true) return '';

            const description = this.hotspotProduct(item)?.description || SAMPLE_PRODUCT_DESCRIPTION;

            return this.escapeHtmlText(
                this.truncateWords(this.stripContent(description), parseInt(item?.limit_words ?? 20), '...')
            );
        },

        escapeHtmlText(value: string) {
            if (!value) return '';

            return String(value)
                .replace(/&/g, '&amp;')
                .replace(/</g, '&lt;')
                .replace(/>/g, '&gt;');
        },

        hotspotBtnAnimationClass(item: any) {
            const a = item?.hotspotsAnimation;
            if (!a || a === 'none') {
                return '';
            }
            return a;
        },
        tooltipContentAnimationClass() {
            const a = (this as any).imageHotspot?.tooltipAnimation;
            if (!a || a === 'none') {
                return 'ecom-animation-none';
            }
            return a;
        },
        hotspotBtnStyle(item: any) {
            const style: any = item.source === 'link' && (this as any).exporting ? { cursor: 'pointer' } : { ...this.cursorBtn };
            const animationName = item.hotspotsAnimation;
            const animationDuration = item.hotspotsAnimationDuration;
            const isLoop =
                item.hotspotAnimationLoop === true ||
                item.hotspotAnimationLoop === 'true' ||
                (Array.isArray(item.hotspotAnimationLoop) &&
                    (item.hotspotAnimationLoop.includes(true) || item.hotspotAnimationLoop.includes('true')));
            if (animationName && animationName !== 'none') {
                style.animationDuration = `${animationDuration || 300}ms`;
                style.transitionProperty = 'transform, opacity, visibility';
                style.animationIterationCount = isLoop ? 'infinite' : '1';
            }
            return style;
        },
        onBuilderHotspotBtnClick(index, e) {
            if (this.exporting || this.isLive) return;
            if (
                this.isEditingHotspotField(index, 'hotspotLabel') &&
                e?.target?.closest?.('.element__image-hotspot--btn-label')
            ) {
                return;
            }
            const isHoverTrigger = this.data.settings?.trigger === 'hover';
            this.$store.commit('builder/setEditingElement', this);
            this.$store.commit('builder/setEditingElementId', this.data.id);
            if (isHoverTrigger) return;
            if (!('tabOpened' in this.data.settings.items)) {
                Object.defineProperty(this.data.settings.items, 'tabOpened', { enumerable: false, writable: true });
            }
            const opened = this.data.settings.items.tabOpened;
            if (opened === index) {
                this.syncHotspotInlineToModel();
                this.$store.commit('builder/setIsContentEditable', false);
                this.inlineItemIndex = null;
                this.inlineEditField = null;
                this.currentEditEl = null;
                this.data.settings.items.tabOpened = -1;
                return;
            }
            this.data.settings.items.tabOpened = index;
        },
        setEditingElement(i, options = {}) {
            if (this.exporting) return;
            this.$store.commit('builder/setEditingElement', this);
            this.$store.commit('builder/setEditingElementId', this.data.id);
            const shouldKeepClosedOnHover =
                this.data.settings?.trigger === 'hover' &&
                !options?.forceOpen &&
                !this.isContentEditable;
            if( !('tabOpened' in this.data.settings.items))
            {
                Object.defineProperty( this.data.settings.items, "tabOpened", { enumerable: false, writable: true } );

            }
            if (shouldKeepClosedOnHover) {
                return;
            }
            this.data.settings.items.tabOpened = i;
        },
        convertImageCard(item) {

            if(!item){
                return
            }
            let { thumbnailCard = {}, product, source = 'custom'} = item;
            if ((source === 'custom' && Object.keys(thumbnailCard).length === 0) ||
                (source === 'product') && !product) {
                return null;
            }
            const featuredImage = this.hotspotProduct(item)?.featured_image;

            return {
                alt: thumbnailCard.alt || thumbnailCard.name,
                src:
                    (source === 'custom'
                        ? thumbnailCard?.value
                        : product?.thumbnail || featuredImage?.src || featuredImage?.url) ||
                    'images/placeholder.png'
            };
        },

        checkLabelHotspots(){
            return this.data.settings.items?.some((x) => x.isShowLabel && x.hotspotLabel);
        },

