                                        type:'line'
                                    },
                                    {
                                        alias:'spacing',
                                        options: {
                                            label: this.$t('spacing'),
                                        }
                                    }
                                ]
                            },
                        ],

                        remove:[
                            {
                                index:0,
                                length:1
                            },
                            {
                                index:2,
                                length:1
                            }
                        ]
                    }
                },
                {
