                    group_title: this.$t('tooltip_content'),
                    selector:
                        ' .ecom__element.element__image-hotspot .element__image-hotspot--content .element__image-hotspot--content-text',
                    },
                    modify:{
                        params:
                        {
                            position:15,
                            fields:[
                                {
                                    alias:'spacing',
                                    options: {
                                        label: this.$t('spacing'),
                                    }
                                }
                            ]
                        }
                    }
                },
                {
                    group_alias:'text',
                    options:{
                         group_name: 'hotspotTooltipPrice',
                        group_title: this.$t('tooltip_price'),
                        selector:' .element__image-hotspot--content-price',
                    },
                    modify:{
                        remove: {
                            length: 1,
                            index: 0
                        },
                        params:
                        [
                            {
                                position: 1,
                                fields: {
                                    type: 'choose',
                                    label: this.$t('alignment'),
                                    name: 'textTextAlign',
                                    options: {
                                        oneline: true,
                                        responsive: true,
                                        type: 'align-full',
                                        values: ['left', 'center', 'right', 'justify']
                                    },
                                    css: {
                                        properties: {
                                            'text-align':''
                                        },
                                        selector: 'root .element__image-hotspot--content-prices'
                                    }
                                }
                            },
                            {
                                position:15,
                                fields:[
                                    {
                                        alias:'spacing',
                                        options: {
                                            label: this.$t('spacing'),
                                        }
                                    }
                                ]
                            }
                        ]
                    }
                },
                {
                    group_alias:'text',
                    options:{
                         group_name: 'hotspotTooltipPriceRegular',
                        group_title: this.$t('tooltip_price_regular'),
                        selector:' .element__image-hotspot--content-price--regular',
                    },
                    modify:{
                        params:
                        {
                            position:15,
                            fields:[
                                {
                                    alias:'spacing',
                                    options: {
