                            ]
                        }
                    }
                },
                {
                    group_alias: 'button',
                    options:{
                        group_name: 'hotspotTooltipButton',
                        group_title: this.$t('tooltip_button'),
                        selector:' .ecom__element.element__image-hotspot .ecom__image-hostpot--content-container .element__image-hotspot--content-btn',
                    },
                    modify:{
                        params:[
                            {
                                position:0,
                                fields:[
                                    {
                                        alias:'justify-content',
                                        options:{
                                            label: this.$t('alignment'),
                                            css:{
                                                selector:'root .ecom-button-default'
                                            }
                                        }
                                    }
                                ]
                            },
                        ]
                    }
                },
                (this.isCaption) ? {
                    group_alias: 'text',
                    options:{
                        group_name: 'hotspotCation',
                        group_title: this.$t('caption'),
                        selector: ' .ecom__element.element__image-hotspot .ecom-image__caption'
                    }
                } : null

            ].filter(x => x);
            return style;
        },
        mouseDown(e, i) {
            if (this.exporting) {
                return;
            }
            if (e.target.closest('.ecom-hotspots-container-tooltip')) {
                return;
            }
            if (this.isContentEditable) {
                return;
            }
            const $target = e.target.closest('.element__image-hotspot--text');
            // Dùng coord div (khớp với ảnh) làm reference tuyệt đối
            const $coord   = this.$el.querySelector('.ecom-element__hotspot-coord');
            const coordRect = ($coord || this.$el).getBoundingClientRect();
            const elRect    = $target.getBoundingClientRect();

            // Ghi nhớ offset từ chuột đến TÂM của element.
            // Điểm tâm duy trì được anchor không bị lệch do button width cố định trên mobile.
            const centerPx = elRect.left + (elRect.width / 2);
            const centerPy = elRect.top + (elRect.height / 2);
            const centerXPercent = ((centerPx - coordRect.left) / coordRect.width) * 100;
            const centerYPercent = ((centerPy - coordRect.top) / coordRect.height) * 100;

            this.drag.grabOffsetCenterX = (e.clientX - centerPx) / coordRect.width  * 100;
            this.drag.grabOffsetCenterY = (e.clientY - centerPy) / coordRect.height * 100;
            this.drag.coordRect         = coordRect;
            this.drag.x = centerXPercent;
            this.drag.y = centerYPercent;

            this.drag.currentEl = $target;
            this.drag.i = i;
            this.idoc().onmousemove = this.onMouseMove;
            this.idoc().onmouseup = this.onMouseUp;
        },
        onHotspotMouseUp(e, index) {
            if (this.exporting) return;
            if (e?.target?.closest?.('.element__image-hotspot--btn')) return;
            this.setEditingElement(index);
        },

        onMouseUp() {
            // 1. Gỡ bỏ sự kiện và trả lại giao diện
            const idoc = this.idoc();
            if (idoc) {
                idoc.onmousemove = null;
                if (idoc.body) {
                    idoc.body.style.userSelect = '';
                    idoc.body.style.cursor = '';
                }
            }

            // 2. Hủy requestAnimationFrame trước khi xóa object drag (Tránh rò rỉ hiệu năng)
            if (this.drag.rafId) {
                cancelAnimationFrame(this.drag.rafId);
            }

            // 3. Cập nhật dữ liệu nếu thực sự có hành động kéo (started)
            let { i, x, y } = this.drag;
            if (i > -1 && this.drag.started && x >= 0 && y >= 0) {
                if (this.hotSpot && this.hotSpot.items && this.hotSpot.items[i]) {
                    this.hotSpot.items[i].horizontalPosition = x;
                    this.hotSpot.items[i].verticalPosition = y;
                    // Đánh dấu item đã dùng cơ chế mới (wrapper-relative)
                    this.hotSpot.items[i].positionV2 = true;
                }
            }

            // 4. Reset trạng thái drag về ban đầu
            Object.assign(this.drag, {
                x: -1,
                y: -1,
                i: -1,
                started: false,
                coordRect: null,
                rafId: null // Reset luôn tại đây
            });
        },

        onMouseMove(e) {
            // Drag only while holding left mouse button.
            if (typeof e?.buttons === 'number' && (e.buttons & 1) !== 1) {
                return;
            }
            // Dùng coordRect đã snapshot tại mouseDown (= image rect tại lúc bắt đầu drag)
            // tránh re-query DOM mỗi frame, đảm bảo consistency suốt drag session
            const coordRect = this.drag.coordRect || this.$el.getBoundingClientRect();

            // Tính vị trí TÂM của element sao cho giữ nguyên khoảng cách với chuột
            const mouseX_Pct = (e.clientX - coordRect.left) / coordRect.width  * 100;
            const mouseY_Pct = (e.clientY - coordRect.top)  / coordRect.height * 100;

            const centerX = mouseX_Pct - this.drag.grabOffsetCenterX;
            const centerY = mouseY_Pct - this.drag.grabOffsetCenterY;

            const x = Math.max(0, Math.min(100, centerX));
            const y = Math.max(0, Math.min(100, centerY));

            if (this.idoc && this.idoc().body) {
                this.idoc().body.style.userSelect = 'none';
                this.idoc().body.style.cursor = 'move';
            }

            if (!this.drag.started && (Math.abs(x - this.drag.x) > 0.5 || Math.abs(y - this.drag.y) > 0.5)) {
                this.drag.started = true;
            }

            if (this.drag.started) {
                this.drag.x = x;
                this.drag.y = y;

                if (!this.drag.rafId) {
                    this.drag.rafId = requestAnimationFrame(() => {
                        if (this.drag.currentEl) {
                            this.drag.currentEl.style.left = `${this.drag.x}%`;
                            this.drag.currentEl.style.top  = `${this.drag.y}%`;
                            this.drag.currentEl.style.transform = 'translate(-50%, -50%)';
                        }
                        this.drag.rafId = null;
                    });
                }
            }
        }
    },
    watch: {
        activeMe(val) {
            if (!val && this.isContentEditable) {
                this.$store.commit('builder/setIsContentEditable', false);
                this.$store.commit('builder/setEditingElementId', '');
                this.syncHotspotInlineToModel();
                this.inlineItemIndex = null;
                this.inlineEditField = null;
                this.currentEditEl = null;
            }
            if (val) {
                this.$store.commit('builder/setEditingElementId', this.data.id);
            }
        },
        isContentEditable() {
            this.isBlur = false;
        },
        isEditingThisElement(val) {
            if (val && this.inlineItemIndex !== null && this.inlineEditField) {
                this.focusHotspotInlineField();
            }
        },
        'data.settings': {
            handler() {
                this.applyAnimationDefaultsIfMissing();
            },
            immediate: true,
            deep: true
        },
        hotspotProductHandlesKey: {
            handler() {
                this.debouncedLoadHotspotProducts();
            },
            immediate: true
        }
    }
};
</script>
