import type { Liquid } from 'liquidjs';
import type { ShopData } from '@/types/shopify.d';
import { decodeHtmlEntities } from '@/utils/string';

/**
 * Shop data được nạp bất đồng bộ sau khi engine đã khởi tạo, nên filter phải đọc
 * qua resolver thay vì giữ giá trị lúc register (nếu không sẽ đóng băng ở null và
 * mọi giá đều rơi về định dạng USD mặc định).
 */
type ShopDataResolver = () => ShopData | null;

const DEFAULT_MONEY_FORMAT = '${{amount}}';
const PLACEHOLDER_PATTERN = /\{\{\s*(\w+)\s*\}\}/g;

function toSafeMoneyValue(value: any): number | null {
    if (value === null || value === undefined || value === '') return null;

    const numberValue = Number(value);
    return Number.isFinite(numberValue) ? numberValue : null;
}

function groupNumber(
    amount: number,
    decimals: number,
    thousandsSeparator: string,
    decimalSeparator: string
): string {
    const fixed = Math.abs(amount).toFixed(decimals);
    const [integerPart, fractionPart] = fixed.split('.');
    const grouped = integerPart.replace(/\B(?=(\d{3})+(?!\d))/g, thousandsSeparator);
    const sign = amount < 0 ? '-' : '';

    return sign + grouped + (fractionPart ? decimalSeparator + fractionPart : '');
}

/**
 * Toàn bộ placeholder Shopify hỗ trợ trong money format.
 * @see https://shopify.dev/docs/api/liquid/filters/money
 */
const PLACEHOLDERS: Record<string, (amount: number) => string> = {
    amount: (amount) => groupNumber(amount, 2, ',', '.'),
    amount_no_decimals: (amount) => groupNumber(amount, 0, ',', '.'),
    amount_with_comma_separator: (amount) => groupNumber(amount, 2, '.', ','),
    amount_no_decimals_with_comma_separator: (amount) => groupNumber(amount, 0, '.', ','),
    amount_with_apostrophe_separator: (amount) => groupNumber(amount, 2, "'", '.'),
    amount_with_space_separator: (amount) => groupNumber(amount, 2, ' ', ','),
    amount_no_decimals_with_space_separator: (amount) => groupNumber(amount, 0, ' ', '.'),
};

/** Placeholder tương ứng khi bỏ phần thập phân (dùng cho money_without_trailing_zeros). */
const NO_DECIMALS_PLACEHOLDERS: Record<string, string> = {
    amount: 'amount_no_decimals',
    amount_with_comma_separator: 'amount_no_decimals_with_comma_separator',
    amount_with_space_separator: 'amount_no_decimals_with_space_separator',
    amount_with_apostrophe_separator: 'amount_no_decimals',
};

function resolveMoneyFormat(shopData: ShopData | null): string {
    // Format có thể về ở dạng HTML-escape (`&lt;span class=money&gt;...`) -> decode
    // để `{{ price | money }}` render ra thẻ thật thay vì chuỗi thẻ.
    return decodeHtmlEntities(shopData?.money_format || shopData?.moneyFormat || DEFAULT_MONEY_FORMAT);
}

function resolveMoneyWithCurrencyFormat(shopData: ShopData | null): string {
    if (shopData?.money_with_currency_format) {
        return decodeHtmlEntities(shopData.money_with_currency_format);
    }

    return `${resolveMoneyFormat(shopData)} ${shopData?.currency || 'USD'}`;
}

/** Placeholder đầu tiên trong format, dùng để suy ra kiểu phân tách của shop. */
function firstPlaceholder(format: string): string {
    const matched = new RegExp(PLACEHOLDER_PATTERN.source).exec(format);
    const key = matched?.[1];

    return key && PLACEHOLDERS[key] ? key : 'amount';
}

function applyFormat(cents: any, format: string, dropDecimals: boolean = false): string {
    const raw = toSafeMoneyValue(cents);
    if (raw === null) return '';

    const amount = raw / 100;

    return format.replace(PLACEHOLDER_PATTERN, (match, key: string) => {
        const resolvedKey = dropDecimals ? (NO_DECIMALS_PLACEHOLDERS[key] ?? key) : key;
        const render = PLACEHOLDERS[resolvedKey];

        return render ? render(amount) : match;
    });
}

/**
 * Format tiền (cents) theo money format của shop — bản đồng bộ dùng ngoài Liquid,
 * cho component render giá trực tiếp trong builder (tương đương `{{ price | money }}`).
 */
export function formatMoney(cents: any, shopData: ShopData | null): string {
    return applyFormat(cents, resolveMoneyFormat(shopData));
}

export function registerMoneyFilters(engine: Liquid, getShopData: ShopDataResolver): void {
    engine.registerFilter('money', (value: any) => {
        return formatMoney(value, getShopData());
    });

    engine.registerFilter('money_with_currency', (value: any) => {
        return applyFormat(value, resolveMoneyWithCurrencyFormat(getShopData()));
    });

    engine.registerFilter('money_without_currency', (value: any) => {
        const raw = toSafeMoneyValue(value);
        if (raw === null) return '';

        // Giữ kiểu phân tách của shop nhưng bỏ toàn bộ ký hiệu tiền tệ.
        const key = firstPlaceholder(resolveMoneyFormat(getShopData()));

        return PLACEHOLDERS[key](raw / 100);
    });

    engine.registerFilter('money_without_trailing_zeros', (value: any) => {
        const raw = toSafeMoneyValue(value);
        if (raw === null) return '';

        const format = resolveMoneyFormat(getShopData());

        return applyFormat(value, format, Number.isInteger(raw / 100));
    });
}
